effect.shader:
#define EPS 0.00001
#define PI 3.14159265359
vec3 toLinear(vec3 s) {
    vec3 lo = s / 12.92;
    vec3 hi = pow((s + 0.055) / 1.055, vec3(2.4));
    return mix(lo, hi, step(vec3(0.04045), s));
}
vec3 toSRGB(vec3 l) {
    vec3 lo = l * 12.92;
    vec3 hi = 1.055 * pow(max(l, 0.0), vec3(1.0 / 2.4)) - 0.055;
    return mix(lo, hi, step(vec3(0.0031308), l));
}
float lum(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}
float getTaps(float q) {
    if (q < 1.5) return 10.0;
    if (q < 2.5) return 18.0;
    return 28.0;
}
vec4 separableBlur(sampler2D tex, vec2 uv, vec2 dir, float radius, float taps) {
    if (radius <= 0.5) return texture2DCv(tex, uv);
    float sigma = radius / 2.14596602;
    sigma = max(sigma, EPS);
    float baseCoeff = 1.0 / (sqrt(2.0 * PI) * sigma);
    float decayRate = exp(-0.5 / (sigma * sigma));
    float decaySq = decayRate * decayRate;
    vec4 acc = texture2DCv(tex, uv) * baseCoeff;
    float wSum = baseCoeff;
    float coeff = baseCoeff;
    float decay = decayRate;
    for (float i = 1.0; i <= 256.0; i += 2.0) {
        if (i > taps) break;
        float p0 = i;
        float p1 = i + 1.0;
        coeff *= decay;
        wSum += 2.0 * coeff;
        float w0 = coeff;
        coeff *= decay;
        decay *= decaySq;
        wSum += 2.0 * coeff;
        float w1 = coeff;
        float wPair = w0 + w1;
        float oPair = (p0*w0 + p1*w1) / max(wPair, EPS);
        vec2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
        vec2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
        acc += texture2DCv(tex, uvA) * wPair;
        acc += texture2DCv(tex, uvB) * wPair;
    }
    return acc / max(wSum, EPS);
}
void main() {
    vec2 uv = acScreenNorm;
    float taps = getTaps(float(quality));
    float r1 = glowRadius * 0.4;
    float r2 = glowRadius * 1.2;
    if (acPass == 0) {
        vec2 dir = vec2(1.0 / getTexSize(inputImg.size).x, 0.0);
        gl_FragColor = separableBlur(inputImg.texture, uv, dir, r1, taps);
        return;
    }
    if (acPass == 1) {
        vec2 dir = vec2(0.0, 1.0 / getTexSize(blurA.size).y);
        gl_FragColor = separableBlur(blurA.texture, uv, dir, r1, taps);
        return;
    }
    if (acPass == 2) {
        vec2 dir = vec2(1.0 / getTexSize(inputImg.size).x, 0.0);
        gl_FragColor = separableBlur(inputImg.texture, uv, dir, r2, taps);
        return;
    }
    if (acPass == 3) {
        vec2 dir = vec2(0.0, 1.0 / getTexSize(blurC.size).y);
        gl_FragColor = separableBlur(blurC.texture, uv, dir, r2, taps);
        return;
    }
    vec4 original = texture2DCv(inputImg.texture, uv);
    vec3 baseRGB = max(original.rgb, 0.0);
    vec3 baseLin = toLinear(baseRGB);
    float baseLum = lum(baseLin);
    vec3 narrowBlur = max(texture2DCv(blurB.texture, uv).rgb, 0.0);
    vec3 wideBlur = max(texture2DCv(blurD.texture, uv).rgb, 0.0);
    vec3 narrowLin = toLinear(narrowBlur);
    vec3 wideLin = toLinear(wideBlur);
    vec3 softBlur = mix(narrowLin, wideLin, glowSoftness);
    float softLum = lum(softBlur);
    float knee = max(glowKnee, EPS);
    float edge = softLum - glowThreshold + knee;
    edge = clamp(edge / (2.0 * knee), 0.0, 1.0);
    edge *= edge;
    float threshMask = max(edge, max(softLum - glowThreshold, 0.0));
    threshMask = threshMask / max(softLum, EPS);
    vec3 glowExtract = softBlur * threshMask;
    vec3 totalGlow = glowExtract * glowAmount;
    if (hlGlow > EPS) {
        float hlMask = smoothstep(hlThreshold - 0.1, hlThreshold + 0.1, baseLum);
        vec3 hlBlur = wideLin * hlMask;
        if (abs(hlSaturation - 1.0) > EPS) {
            float hlL = lum(hlBlur);
            hlBlur = mix(vec3(hlL), hlBlur, hlSaturation);
        }
        totalGlow += hlBlur * hlGlow * 0.5;
        if (hlWrap > EPS) {
            float wrapMask = smoothstep(hlThreshold, hlThreshold + 0.3, baseLum);
            vec3 wrapGlow = wideLin * wrapMask * hlWrap * 0.2;
            totalGlow += wrapGlow;
        }
    }
    if (midGlow > EPS) {
        float midMask = 1.0 - abs(baseLum - 0.5) / max(midRange, EPS);
        midMask = clamp(midMask, 0.0, 1.0);
        midMask *= midMask;
        totalGlow += softBlur * midMask * midGlow * 0.3;
    }
    if (shGlow > EPS) {
        float shMask = smoothstep(0.3, 0.0, baseLum);
        totalGlow += narrowLin * shMask * shGlow * 0.2;
        if (shLift > EPS) {
            totalGlow += shLift * shMask;
        }
    }
    if (colorPreserve > EPS) {
        float glowLum = lum(totalGlow);
        float baseSatRatio = lum(baseLin);
        if (baseSatRatio > EPS && glowLum > EPS) {
            vec3 baseColor = baseLin / max(baseSatRatio, EPS);
            vec3 coloredGlow = baseColor * glowLum;
            totalGlow = mix(totalGlow, coloredGlow, colorPreserve * 0.5);
        }
    }
    if (abs(glowSatBoost - 1.0) > EPS) {
        float gL = lum(totalGlow);
        totalGlow = mix(vec3(gL), totalGlow, glowSatBoost);
    }
    if (abs(glowWarmth) > EPS) {
        totalGlow.r += glowWarmth * 0.04 * lum(totalGlow);
        totalGlow.b -= glowWarmth * 0.03 * lum(totalGlow);
    }
    if (glowTintStrength > EPS) {
        vec3 tintLin = toLinear(glowTint.rgb);
        totalGlow = mix(totalGlow, totalGlow * tintLin, glowTintStrength);
    }
    if (atmoAmount > EPS) {
        vec3 atmoLin = toLinear(atmoColor.rgb);
        float atmoMask = pow(max(lum(softBlur), 0.0), 1.0 + atmoDensity * 2.0);
        vec3 atmosphere = atmoLin * atmoMask;
        totalGlow += atmosphere * atmoAmount * 0.15;
    }
    totalGlow = max(totalGlow, 0.0);
    if (glowOnly) {
        vec3 glowView = toSRGB(totalGlow);
        gl_FragColor = vec4(clamp(glowView, 0.0, 1.0), 1.0);
        return;
    }
    vec3 composited;
    float bm = float(blendMode);
    if (bm < 1.5) {
        composited = baseLin + totalGlow;
    } else if (bm < 2.5) {
        vec3 baseS = baseRGB;
        vec3 glowS = toSRGB(totalGlow);
        composited = toLinear(1.0 - (1.0 - baseS) * (1.0 - clamp(glowS, 0.0, 1.0)));
    } else if (bm < 3.5) {
        vec3 baseS = baseRGB;
        vec3 glowS = toSRGB(clamp(totalGlow, 0.0, 1.0));
        vec3 r;
        r.r = (glowS.r<0.5) ? 2.0*baseS.r*glowS.r+baseS.r*baseS.r*(1.0-2.0*glowS.r) : 2.0*baseS.r*(1.0-glowS.r)+sqrt(max(baseS.r,0.0))*(2.0*glowS.r-1.0);
        r.g = (glowS.g<0.5) ? 2.0*baseS.g*glowS.g+baseS.g*baseS.g*(1.0-2.0*glowS.g) : 2.0*baseS.g*(1.0-glowS.g)+sqrt(max(baseS.g,0.0))*(2.0*glowS.g-1.0);
        r.b = (glowS.b<0.5) ? 2.0*baseS.b*glowS.b+baseS.b*baseS.b*(1.0-2.0*glowS.b) : 2.0*baseS.b*(1.0-glowS.b)+sqrt(max(baseS.b,0.0))*(2.0*glowS.b-1.0);
        composited = toLinear(r);
    } else {
        vec3 baseS = baseRGB;
        vec3 glowS = toSRGB(clamp(totalGlow, 0.0, 1.0));
        vec3 r;
        r.r = (baseS.r<0.5) ? 2.0*baseS.r*glowS.r : 1.0-2.0*(1.0-baseS.r)*(1.0-glowS.r);
        r.g = (baseS.g<0.5) ? 2.0*baseS.g*glowS.g : 1.0-2.0*(1.0-baseS.g)*(1.0-glowS.g);
        r.b = (baseS.b<0.5) ? 2.0*baseS.b*glowS.b : 1.0-2.0*(1.0-baseS.b)*(1.0-glowS.b);
        composited = toLinear(r);
    }
    vec3 fin = toSRGB(max(composited, 0.0));
    if (ditherAmt > EPS) {
        vec2 px = floor(getTexSize(inputImg.size) * uv);
        float n1 = fract(sin(dot(px, vec2(12.9898, 78.233))) * 43758.5453);
        float n2 = fract(sin(dot(px, vec2(24.123, 17.321))) * 12345.6789);
        float n3 = fract(sin(dot(px, vec2(93.989, 67.345))) * 98765.4321);
        fin += (vec3(n1, n2, n3) - 0.5) * ditherAmt;
    }
    fin = mix(baseRGB, fin, globalMix);
    fin = clamp(fin, 0.0, 1.0);
    gl_FragColor = vec4(fin, original.a);
}
